INSERT INTO public.programs (id, category_id, title, slug, subtitle, description, short_description, thumbnail_url, gallery_urls, duration_weeks, duration_label, level, delivery_mode, price, original_price, currency, is_featured, is_active, is_published, rating, review_count, enrollment_count, curriculum, outcomes, requirements, seo_title, seo_description, seo_keywords, order_index, created_at, updated_at)
VALUES
  ('5a5ae21a-3905-4bdb-9499-fdb38bc6de35', 'cda12072-aa57-44b6-a57d-892d31ae7111', 'Freelancing Mastery Bootcamp', 'freelancing-mastery-bootcamp', 'Land your first $500/month client within 30 days', 'Learn how to create winning profiles, write proposals that convert, price your services, manage clients, and scale your freelance income from zero to $1,000+ per month.', 'A comprehensive 6-week bootcamp teaching you how to build a sustainable freelancing career on Upwork, Fiverr, and other global platforms.', 'https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 6, '6 Weeks', 'beginner', 'online', 15000.00, 25000.00, 'KES', true, true, true, 4.80, 234, 1240, NULL, ARRAY['Set up a professional freelancing profile', 'Write proposals that win contracts', 'Earn $500+ per month consistently', 'Manage multiple clients professionally', 'Build a 5-star reputation online']::text[], ARRAY['Basic computer skills', 'Reliable internet connection', 'Willingness to learn and hustle']::text[], NULL, NULL, NULL, 1, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00'),
  ('984c341d-41b0-478b-bdf7-895b0fda6ffa', 'aa5f7e19-f294-45fb-914b-f3713ad74adf', 'E-Commerce Empire Builder', 'ecommerce-empire-builder', 'Build a profitable online store from scratch', 'Master product research, store setup, SEO, paid advertising, and fulfilment to build an e-commerce business that generates consistent revenue.', 'Learn to build and run a profitable e-commerce business selling products locally and internationally using Shopify, Amazon, and Jumia.', 'https://images.pexels.com/photos/230544/pexels-photo-230544.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 8, '8 Weeks', 'beginner', 'online', 18000.00, 30000.00, 'KES', true, true, true, 4.70, 189, 980, NULL, ARRAY['Launch a fully functional online store', 'Source and list profitable products', 'Run profitable Facebook & Google ads', 'Process orders and manage fulfilment', 'Scale to KSh 100,000+ monthly revenue']::text[], ARRAY['Basic smartphone or laptop', 'KSh 5,000 startup capital recommended']::text[], NULL, NULL, NULL, 2, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00'),
  ('1740e1bd-4c4b-4ad7-a0de-cf13ed4ad4ac', '173dd97f-5f09-4228-86e2-3649b653c184', 'Digital Marketing Professional', 'digital-marketing-professional', 'Master SEO, Social Media, and Paid Ads', 'A hands-on 10-week program covering all major digital marketing channels. Work on real client campaigns and build a portfolio that gets you hired.', 'Become a certified digital marketer. Learn SEO, Google Ads, Facebook Ads, email marketing, and analytics to help businesses grow online.', 'https://images.pexels.com/photos/905163/pexels-photo-905163.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 10, '10 Weeks', 'intermediate', 'hybrid', 22000.00, 35000.00, 'KES', true, true, true, 4.90, 312, 1560, NULL, ARRAY['Rank websites on Google page 1', 'Run profitable paid ad campaigns', 'Grow social media accounts to 10K+', 'Create data-driven marketing strategies', 'Land marketing jobs paying 80K+ monthly']::text[], ARRAY['Basic internet knowledge', 'Social media account', 'Analytical mindset']::text[], NULL, NULL, NULL, 3, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00'),
  ('c3fe3181-8a8d-4ca2-a6d0-348c6e97b1cc', '315cd39a-afa8-4af2-b5c4-d079261c3acf', 'Content Creation & Monetization', 'content-creation-monetization', 'Turn your passion into a paid content empire', 'Learn video production, copywriting, social media growth strategies, brand partnerships, and passive income through content creation.', 'Build a profitable YouTube channel, blog, or social media brand. Learn how to create engaging content and monetize across multiple platforms.', 'https://images.pexels.com/photos/3062541/pexels-photo-3062541.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 8, '8 Weeks', 'beginner', 'online', 12000.00, 20000.00, 'KES', false, true, true, 4.60, 156, 720, NULL, ARRAY['Create professional-quality videos', 'Grow to 1,000+ subscribers in 90 days', 'Monetize through AdSense and brand deals', 'Build an email list of 500+ subscribers', 'Earn KSh 50,000+ monthly from content']::text[], ARRAY['Smartphone with camera', 'Passion for sharing knowledge', 'Consistency and creativity']::text[], NULL, NULL, NULL, 4, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00'),
  ('9dbf92e8-6e7e-4992-949b-e9f68fb9e9e1', '3e23699c-b84a-415f-a6a4-440ea0fa24fa', 'Full-Stack Web Development', 'full-stack-web-development', 'Build websites and apps for clients worldwide', 'A comprehensive 16-week program taking you from complete beginner to job-ready developer. Build 5 portfolio projects and land your first developer client.', 'Learn HTML, CSS, JavaScript, React, and Node.js to build professional websites and web applications for clients globally.', 'https://images.pexels.com/photos/574071/pexels-photo-574071.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 16, '16 Weeks', 'beginner', 'online', 35000.00, 50000.00, 'KES', true, true, true, 4.90, 445, 890, NULL, ARRAY['Build full-stack web applications', 'Deploy apps to the cloud', 'Charge $500-$2,000 per project', 'Land remote developer jobs', 'Build a portfolio of 5+ projects']::text[], ARRAY['Basic computer literacy', 'Problem-solving mindset', 'At least 10 hours per week']::text[], NULL, NULL, NULL, 5, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00'),
  ('134bf7f2-bbdf-41b5-a9ef-834403ffc4a6', 'a179ebe4-8c87-4ff0-bdf8-be8ffb342593', 'Forex & Crypto Trading Mastery', 'forex-crypto-trading-mastery', 'Trade profitably with proven strategies', 'A structured 6-week program teaching you how to read charts, identify setups, manage risk, and build a consistent trading edge in financial markets.', 'Learn professional forex and cryptocurrency trading. Master technical analysis, risk management, and trading psychology.', 'https://images.pexels.com/photos/6801648/pexels-photo-6801648.jpeg?auto=compress&cs=tinysrgb&w=800', NULL, 6, '6 Weeks', 'intermediate', 'online', 20000.00, 32000.00, 'KES', false, true, true, 4.50, 201, 650, NULL, ARRAY['Read and analyse price charts', 'Execute trades with proper risk management', 'Build a consistently profitable trading system', 'Grow a trading account from $100 to $1,000+', 'Understand market psychology']::text[], ARRAY['Basic maths and logical thinking', 'Trading capital (min $50 recommended)', 'Emotional discipline']::text[], NULL, NULL, NULL, 6, '2026-07-10 17:45:38.405171+00', '2026-07-10 17:45:38.405171+00')
