VALUES
  ('05f7c54c-b511-4276-8cbd-39f042113c0e', NULL, 'David Kamau', 'Head of Freelancing & E-Commerce', 'David is a top-rated Upwork freelancer with over $250,000 earned online. He has trained over 3,000 students across East Africa and is passionate about helping people escape the 9-to-5.', 'https://images.pexels.com/photos/2379004/pexels-photo-2379004.jpeg?auto=compress&cs=tinysrgb&w=400', 'david@kazilink.academy', NULL, ARRAY['Freelancing', 'E-Commerce', 'Upwork', 'Fiverr']::text[], NULL, 4.90, 312, true, true, 1, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('fe780be3-0d64-4dbc-a0e6-9a15d176e6d2', NULL, 'Grace Wanjiku', 'Digital Marketing Lead', 'Grace is a certified Google and Meta ads specialist with 7+ years helping brands grow their online presence. She has managed over $500K in ad spend for brands across Africa.', 'https://images.pexels.com/photos/3796217/pexels-photo-3796217.jpeg?auto=compress&cs=tinysrgb&w=400', 'grace@kazilink.academy', NULL, ARRAY['SEO', 'Google Ads', 'Facebook Ads', 'Social Media Marketing']::text[], NULL, 4.80, 278, true, true, 2, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('6e489341-a75d-4567-a6fb-bd5c22d86071', NULL, 'Brian Ochieng', 'Full-Stack Developer & Tech Lead', 'Brian is a senior full-stack developer with experience at global tech companies. He has built 50+ web and mobile applications and loves making coding accessible to everyone.', 'https://images.pexels.com/photos/1222271/pexels-photo-1222271.jpeg?auto=compress&cs=tinysrgb&w=400', 'brian@kazilink.academy', NULL, ARRAY['JavaScript', 'React', 'Node.js', 'Python', 'Mobile Apps']::text[], NULL, 4.90, 445, true, true, 3, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('3dd315dc-046c-4037-a7ab-1f4d33d648ae', NULL, 'Amina Hassan', 'Content & Creator Economy Coach', 'Amina built her YouTube channel to 120K subscribers and earns KSh 300,000+ monthly from content. She teaches creators how to find their voice and monetise their passion.', 'https://images.pexels.com/photos/3756679/pexels-photo-3756679.jpeg?auto=compress&cs=tinysrgb&w=400', 'amina@kazilink.academy', NULL, ARRAY['YouTube', 'Content Strategy', 'Brand Deals', 'Blogging']::text[], NULL, 4.70, 189, true, true, 4, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('0fac2e0c-da28-4b30-b96a-34d2b8311bea', NULL, 'James Mwangi', 'Forex & Investment Specialist', 'James is a certified financial trader with 8+ years of professional trading experience. He has taught thousands of Africans how to trade forex and crypto profitably.', 'https://images.pexels.com/photos/937481/pexels-photo-937481.jpeg?auto=compress&cs=tinysrgb&w=400', 'james@kazilink.academy', NULL, ARRAY['Forex Trading', 'Cryptocurrency', 'Technical Analysis', 'Risk Management']::text[], NULL, 4.60, 201, false, true, 5, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00')
