INSERT INTO public.testimonials (id, program_id, student_name, student_title, student_avatar_url, content, rating, income_before, income_after, video_url, is_featured, is_published, order_index, created_at)
VALUES
  ('3d24e508-c58c-4bde-93b1-49f37df4b28a', NULL, 'Sarah Njeri', 'Freelance Graphic Designer, Nairobi', 'https://images.pexels.com/photos/1239291/pexels-photo-1239291.jpeg?auto=compress&cs=tinysrgb&w=200', 'Before joining Kazilink, I was struggling on KSh 15,000 a month as a shop attendant. After completing the Freelancing Mastery Bootcamp, I landed my first Fiverr client within 2 weeks. I now earn KSh 120,000+ monthly designing logos for clients in the US and UK.', 5, 'KSh 15,000/month', 'KSh 120,000+/month', NULL, true, true, 1, '2026-07-10 17:47:04.031223+00'),
  ('d5f6f40b-218d-4fa4-8066-e2ba3963f76c', NULL, 'Michael Otieno', 'E-Commerce Entrepreneur, Kisumu', 'https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=200', 'I was skeptical at first. But the E-Commerce Empire Builder program taught me exactly how to find profitable products and run ads. Within 3 months of graduating, my Shopify store was generating KSh 250,000 in monthly revenue. Best investment I ever made.', 5, 'KSh 45,000/month', 'KSh 250,000+/month', NULL, true, true, 2, '2026-07-10 17:47:04.031223+00'),
  ('83eb9325-4e86-4c28-b45f-bc8e50e566d8', NULL, 'Fatuma Ali', 'Digital Marketing Manager, Mombasa', 'https://images.pexels.com/photos/3769021/pexels-photo-3769021.jpeg?auto=compress&cs=tinysrgb&w=200', 'The Digital Marketing Professional program is world-class. The trainers are practitioners, not just teachers. I got a job paying KSh 85,000/month just 2 months after completing the course. My employer said my portfolio was the best she had ever seen from a fresh graduate.', 5, 'Unemployed', 'KSh 85,000/month', NULL, true, true, 3, '2026-07-10 17:47:04.031223+00'),
  ('cf1a47e9-89b0-46a2-919e-4437ba255ad4', NULL, 'Peter Kariuki', 'Full-Stack Developer, Nairobi', 'https://images.pexels.com/photos/846741/pexels-photo-846741.jpeg?auto=compress&cs=tinysrgb&w=200', 'As someone with no coding background whatsoever, I was nervous. Brian made everything so simple and practical. I built my first commercial website at week 8. By week 16, I had 3 clients and was charging $800 per project. Kazilink changed my life.', 5, 'KSh 30,000/month', '$2,400+/month', NULL, true, true, 4, '2026-07-10 17:47:04.031223+00'),
  ('6c0033e7-03bf-4e6b-932a-f235a1d5a743', NULL, 'Winnie Chebet', 'Content Creator & YouTuber, Eldoret', 'https://images.pexels.com/photos/3756681/pexels-photo-3756681.jpeg?auto=compress&cs=tinysrgb&w=200', 'Amina''s content creation course gave me the blueprint I needed. I went from 200 subscribers to 45,000 in 6 months following her strategy. I now earn from YouTube AdSense, brand partnerships, and digital products. My content business earns KSh 180,000+ monthly.', 5, 'KSh 0 from content', 'KSh 180,000+/month', NULL, true, true, 5, '2026-07-10 17:47:04.031223+00'),
  ('00a4f021-3559-41a8-9277-047b01708b41', NULL, 'Hassan Abdullahi', 'Forex Trader, Garissa', 'https://images.pexels.com/photos/3785104/pexels-photo-3785104.jpeg?auto=compress&cs=tinysrgb&w=200', 'James taught me to think like a professional trader, not a gambler. After 3 months of practice following his strategy, my account grew from $200 to $1,800. The risk management lessons alone were worth 10x the course fee.', 4, '$0 trading profit', '$400+/month consistent', NULL, false, true, 6, '2026-07-10 17:47:04.031223+00')
