INSERT INTO public.blog_posts (id, category_id, author_id, title, slug, excerpt, content, thumbnail_url, tags, is_featured, is_published, published_at, view_count, seo_title, seo_description, seo_keywords, read_time_minutes, created_at, updated_at)
VALUES
  ('ad52f7da-1b87-4593-b541-6b7224b54193', 'd019fce4-f39b-41c9-bca4-7dd40675e269', NULL, 'How Sarah Went From KSh 15K to KSh 120K/Month as a Freelancer', 'sarah-freelancer-success-story', 'A step-by-step account of how a shop attendant in Nairobi transformed her income in just 3 months after completing our Freelancing Mastery Bootcamp.', 'Full story content here...', 'https://images.pexels.com/photos/3184465/pexels-photo-3184465.jpeg?auto=compress&cs=tinysrgb&w=800', ARRAY['freelancing', 'success story', 'fiverr', 'kenya']::text[], true, true, '2026-07-05 17:47:04.031223+00', 2340, NULL, NULL, NULL, 7, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('d244e94d-4542-4809-b0ca-386879be965a', 'ee78b01b-5c13-4ce3-a996-d87cca92d2b2', NULL, '10 Upwork Profile Tips That Will Get You Your First Client Fast', '10-upwork-profile-tips-first-client', 'Your Upwork profile is your digital storefront. These 10 proven strategies will make clients choose you over thousands of other freelancers.', 'Full article content here...', 'https://images.pexels.com/photos/3184339/pexels-photo-3184339.jpeg?auto=compress&cs=tinysrgb&w=800', ARRAY['upwork', 'freelancing', 'tips', 'profile']::text[], true, true, '2026-06-28 17:47:04.031223+00', 5670, NULL, NULL, NULL, 9, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('340942dd-e370-4ac9-91d2-6bf306154c30', '73be1490-2e73-44e5-8bb3-3a1a7d2c47c4', NULL, 'The Complete Guide to Facebook Ads for Kenyan Businesses in 2026', 'complete-guide-facebook-ads-kenya-2026', 'Everything you need to know about running profitable Facebook and Instagram ad campaigns targeting Kenyan customers.', 'Full article content here...', 'https://images.pexels.com/photos/905163/pexels-photo-905163.jpeg?auto=compress&cs=tinysrgb&w=800', ARRAY['facebook ads', 'digital marketing', 'kenya', '2026']::text[], false, true, '2026-06-20 17:47:04.031223+00', 3890, NULL, NULL, NULL, 12, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('3b3cb609-0d88-4b5d-a426-f02f941d390d', '4a6f3549-52be-4613-8a0f-c226a88b43be', NULL, 'How to Start a Dropshipping Business in Kenya with Zero Inventory', 'start-dropshipping-kenya-zero-inventory', 'Dropshipping lets you sell products online without holding stock. Here''s how to get started in Kenya with as little as KSh 5,000.', 'Full article content here...', 'https://images.pexels.com/photos/230544/pexels-photo-230544.jpeg?auto=compress&cs=tinysrgb&w=800', ARRAY['dropshipping', 'ecommerce', 'kenya', 'shopify']::text[], false, true, '2026-06-10 17:47:04.031223+00', 7230, NULL, NULL, NULL, 11, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00')
