  ('51981baf-f3af-4daf-841b-b344036ea593', 'Free Freelancing Webinar', 'FREE Webinar: How to Land Your First $1,000 Client', 'Live on Zoom – July 20th, 7PM EAT', 'Join our free masterclass and learn the exact framework our graduates use to land high-paying freelance clients. No experience needed.', 'hero_banner', ARRAY['homepage']::text[], 'https://images.pexels.com/photos/4226140/pexels-photo-4226140.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, NULL, 'Register Free', '/contact?subject=webinar', 'primary', '#155e75', NULL, NULL, 8, NULL, 'active', '2026-07-11 11:42:46.889507+00', '2026-07-20 21:00:00+00', 0, 0, '2026-07-11 11:42:46.889507+00', '2026-07-11 11:42:46.889507+00'),
  ('5f729cd4-6e47-4230-a43d-fef5b0e68e3e', 'E-Commerce Bootcamp Flash Sale', 'Flash Sale: E-Commerce Empire Builder', '48 hours only – KES 5,000 off regular price', 'Start your online store journey with our most popular e-commerce program. Offer ends midnight Friday!', 'carousel', ARRAY['homepage']::text[], 'https://images.pexels.com/photos/4467687/pexels-photo-4467687.jpeg?auto=compress&cs=tinysrgb&w=1200', NULL, NULL, 'Claim Discount', '/programs/ecommerce-empire-builder', 'primary', '#075985', NULL, NULL, 5, NULL, 'active', '2026-07-11 11:42:46.889507+00', '2026-07-13 11:42:46.889507+00', 0, 0, '2026-07-11 11:42:46.889507+00', '2026-07-11 11:42:46.889507+00')
