INSERT INTO public.team_members (id, full_name, title, bio, avatar_url, email, social_links, department, is_featured, is_active, order_index, created_at)
VALUES
  ('12525ada-774d-4e77-a3f6-48ff0caa6ab6', 'Dr. Purity Muthoni', 'Founder & CEO', 'Former software engineer turned edu-preneur. Purity founded Kazilink after seeing the potential of remote work to transform African livelihoods. She has been featured in TechCabal, Business Daily, and Forbes Africa.', 'https://images.pexels.com/photos/3756679/pexels-photo-3756679.jpeg?auto=compress&cs=tinysrgb&w=400', NULL, NULL, 'Leadership', true, true, 1, '2026-07-10 17:47:04.031223+00'),
  ('b49f6241-9818-4634-8cf3-6d719409aead', 'Kevin Ndungu', 'Chief Operating Officer', 'Kevin brings 10+ years of operations and education management experience. He oversees program delivery, student success, and strategic partnerships.', 'https://images.pexels.com/photos/2379004/pexels-photo-2379004.jpeg?auto=compress&cs=tinysrgb&w=400', NULL, NULL, 'Leadership', true, true, 2, '2026-07-10 17:47:04.031223+00'),
  ('3dd0b5e6-6415-45d0-abff-a7d72d2fa3fc', 'Lucy Wairimu', 'Head of Student Success', 'Lucy ensures every student gets the support they need to succeed. She leads our mentorship programs and alumni community of 12,500+ graduates.', 'https://images.pexels.com/photos/3796217/pexels-photo-3796217.jpeg?auto=compress&cs=tinysrgb&w=400', NULL, NULL, 'Student Success', true, true, 3, '2026-07-10 17:47:04.031223+00'),
  ('2f7b3641-8039-4ade-a3bb-583b96cb9697', 'Eric Kamande', 'Head of Technology', 'Eric leads our platform development and ensures students have the best learning technology experience possible.', 'https://images.pexels.com/photos/1222271/pexels-photo-1222271.jpeg?auto=compress&cs=tinysrgb&w=400', NULL, NULL, 'Technology', false, true, 4, '2026-07-10 17:47:04.031223+00')
INSERT INTO public.faqs (id, category, question, answer, order_index, is_published, created_at, updated_at)
VALUES
  ('d21e2bcd-1a20-4916-98c2-d25d7399ddf8', 'general', 'What is Kazilink Digital Academy?', 'Kazilink Digital Academy is Kenya''s leading online income skills training institution. We offer practical, results-focused training programs that teach you how to earn money online through freelancing, e-commerce, digital marketing, content creation, coding, and trading.', 1, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('9af840f2-e58d-45ca-a034-cf8dbd5b18bb', 'general', 'Are the courses online or in-person?', 'We offer both online and hybrid (in-person + online) programs. Each cohort listing shows the delivery format. Online courses are conducted via Zoom or Google Meet, making them accessible from anywhere in Africa.', 2, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('6678720d-d313-4816-a001-25da93bac702', 'general', 'How long does each program take?', 'Program durations vary from 6 weeks to 16 weeks depending on the course. Each program page shows the exact duration, schedule, and weekly time commitment required.', 3, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('904570b6-fb94-464a-b269-5d7f39d119c4', 'booking', 'How do I book a course?', 'Visit our Booking page, choose your program and preferred cohort, fill in your registration details, and submit your payment. Your booking will be reviewed and confirmed by our team within 24 hours.', 4, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('25aa6c56-4f27-414c-a278-27023f1ee44b', 'booking', 'What payment methods are accepted?', 'We accept M-Pesa, bank transfer, Stripe (Visa/Mastercard), and PayPal. Payment plans and installments are also available for select programs. Contact us to discuss flexible payment options.', 5, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('e9cc26bb-c08f-4098-8c99-31b4ec10cd37', 'booking', 'Can I get a refund if I change my mind?', 'We offer a 7-day refund policy from the date of booking confirmation, provided the cohort has not yet started. Please see our full refund policy for terms and conditions.', 6, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('fdf67785-624e-4e04-912f-074ab959f80f', 'programs', 'Do I need prior experience to join?', 'Most of our programs are designed for beginners. Each program page lists the specific requirements. If you can use a smartphone and have an internet connection, you can get started.', 7, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('3db1b30a-4de1-4668-bf3f-97590306dc77', 'programs', 'Do I receive a certificate upon completion?', 'Yes. All graduates receive a Kazilink Digital Academy digital certificate upon successful completion of their program and assessments. Certificates can be shared on LinkedIn and used with clients.', 8, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('648fc69e-1016-41e9-9df0-031be5349571', 'programs', 'Will I get support after completing the course?', 'Yes. All graduates get lifetime access to our alumni WhatsApp community, monthly Q&A sessions, and job board access. We are committed to your long-term success.', 9, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('c91afbf5-2281-473f-a6fb-708942e9e42c', 'payments', 'Are payment plans available?', 'Yes. We offer flexible installment plans for most programs. You can pay in 2 or 3 installments. A deposit is required to secure your seat. Contact us to set up a payment plan.', 10, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00'),
  ('a03b7ba1-dd72-4cc1-a326-29a6720305bb', 'payments', 'Are there scholarships available?', 'We offer need-based scholarships and youth empowerment bursaries for deserving candidates. Applications are reviewed quarterly. Visit our Pricing page for details.', 11, true, '2026-07-10 17:47:04.031223+00', '2026-07-10 17:47:04.031223+00')
